def decodeImp : List UInt8 → Except String (List UInt8) :=
fun s =>
  (have decoded := #[];
    have val := 0;
    have bits := 0;
    do
    let r ←
      forIn s ⟨none, bits, decoded, val⟩ fun c r =>
          have r := r.snd;
          have bits := r.fst;
          have x := r.snd;
          have decoded := x.fst;
          have val := x.snd;
          match revAlphabet c with
          | none => pure (ForInStep.done ⟨some (Except.error "Non-base32 digit found"), bits, decoded, val⟩)
          | some k =>
            have val := val <<< 5 ||| k;
            have bits := bits + 5;
            if bits ≥ 8 then
              have bits := bits - 8;
              have decoded := decoded.push (UInt8.ofNat (val >>> bits &&& 255));
              do
              pure PUnit.unit
              pure (ForInStep.yield ⟨none, bits, decoded, val⟩)
            else do
              pure PUnit.unit
              pure (ForInStep.yield ⟨none, bits, decoded, val⟩)
    match r.snd with
      | ⟨bits, decoded, val⟩ =>
        have __do_jp := fun y => pure (Except.ok decoded.toList);
        match r.fst with
        | none => do
          let y ← pure PUnit.unit
          __do_jp y
        | some a => pure a).run
